struct Swapchain {
    XrSwapchain handle = XR_NULL_HANDLE;
    std::vector<XrSwapchainImageVulkanKHR> images;
    // Echo always makes an image view on each image's foveation (fragment density) map:
    // NRadEngine::CVR::Resize ignores the result of GetTextureSwapChainBufferFoveationVulkan.
    std::vector<VkImage> fdm;
    std::vector<VkDeviceMemory> fdmMemory;
    uint32_t fdmWidth = 0, fdmHeight = 0;
    int32_t width = 0, height = 0, arraySize = 1;
    int32_t acquired = -1;   // image index acquired this frame, -1 = none
    int32_t echoLast = -1;   // the image Echo rendered last frame (it goes round-robin)
    uint64_t mismatches = 0;
    // flip by copy (g.flipCopy): what's submitted is this swapchain, Echo's image copied in
    // upside down
    XrSwapchain out = XR_NULL_HANDLE;
    std::vector<XrSwapchainImageVulkanKHR> outImages;
    int32_t outAcquired = -1;
};

struct ViewCache { double time = -1; XrView views[2]; };

struct Hand {
    XrPath path = XR_NULL_PATH;
    XrSpace grip = XR_NULL_HANDLE, aim = XR_NULL_HANDLE;
    // acceleration, which OpenXR doesn't report: from the change in velocity, smoothed
    double lastTime = 0;
    vr::Vector3f lastLinear{}, lastAngular{}, linearAccel{}, angularAccel{};
    double peakSpeed = 0;   // m/s since the last log line
    // the velocities of this frame's display-time answer, and when it was given
    vr::Vector3f dispLinear{}, dispAngular{};
    double dispAsked = -1;
    double dispTime = 0;
};

